u_ai_tool.u_parameters:
{
  "type": "object",
  "properties": {
    "catalog_item_name": {
      "type": "string",
      "description": "Name of the catalog item to request (e.g., 'Laptop', 'VPN Access')"
    },
    "quantity": {
      "type": "integer",
      "description": "Quantity needed (default 1)"
    },
    "justification": {
      "type": "string",
      "description": "Business justification for the request"
    },
    "requested_for": {
      "type": "string",
      "description": "User to request for (if different from current user)"
    },
    "urgency": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high"
      ],
      "description": "Request urgency"
    },
    "variables": {
      "type": "object",
      "description": "Catalog item specific variables (e.g., {laptop_type: 'Developer', os: 'Windows 11'})"
    }
  },
  "required": [
    "catalog_item_name",
    "justification"
  ]
}

u_ai_tool.u_script:
(function(args, userId) {
    // Validate required fields
    if (!args.catalog_item_name || !args.justification) {
        return {
            success: false,
            error: 'Missing required fields: catalog_item_name, justification'
        };
    }

    // Find the catalog item
    var catItemGR = new GlideRecord('sc_cat_item');
    catItemGR.addQuery('name', 'CONTAINS', args.catalog_item_name);
    catItemGR.addQuery('active', true);
    catItemGR.setLimit(1);
    catItemGR.query();

    if (!catItemGR.next()) {
        // Try exact match
        catItemGR = new GlideRecord('sc_cat_item');
        catItemGR.addQuery('name', args.catalog_item_name);
        catItemGR.addQuery('active', true);
        catItemGR.setLimit(1);
        catItemGR.query();

        if (!catItemGR.next()) {
            return {
                success: false,
                error: 'Catalog item not found: ' + args.catalog_item_name
            };
        }
    }

    // Create the request
    var reqGR = new GlideRecord('sc_request');
    reqGR.initialize();

    // Set requester
    if (args.requested_for) {
        var reqForGR = new GlideRecord('sys_user');
        if (reqForGR.get(args.requested_for)) {
            reqGR.requested_for = args.requested_for;
        } else {
            reqForGR.addQuery('user_name', args.requested_for);
            reqForGR.setLimit(1);
            reqForGR.query();
            if (reqForGR.next()) {
                reqGR.requested_for = reqForGR.getUniqueValue();
            }
        }
    } else {
        reqGR.requested_for = userId;
    }

    reqGR.requested_by = userId;
    reqGR.short_description = 'Request for ' + catItemGR.name;
    reqGR.description = args.justification;
    reqGR.priority = args.urgency || '3'; // Default to moderate

    var reqSysId = reqGR.insert();

    if (!reqSysId) {
        return {
            success: false,
            error: 'Failed to create request'
        };
    }

    // Create the requested item
    var reqItemGR = new GlideRecord('sc_req_item');
    reqItemGR.initialize();
    reqItemGR.request = reqSysId;
    reqItemGR.cat_item = catItemGR.getUniqueValue();
    reqItemGR.short_description = catItemGR.name;
    reqItemGR.quantity = args.quantity || 1;
    reqItemGR.description = args.justification;

    // Set variables if provided
    if (args.variables) {
        for (var key in args.variables) {
            if (args.variables.hasOwnProperty(key)) {
                // Try to find the variable
                var varGR = new GlideRecord('item_option_new');
                varGR.addQuery('name', key);
                varGR.addQuery('cat_item', catItemGR.getUniqueValue());
                varGR.setLimit(1);
                varGR.query();
                if (varGR.next()) {
                    // Create variable value record
                    var varValueGR = new GlideRecord('sc_item_option');
                    varValueGR.initialize();
                    varValueGR.item_type = varGR.getUniqueValue();
                    varValueGR.request_item = reqItemGR.sys_id;
                    varValueGR.value = args.variables[key];
                    varValueGR.insert();
                }
            }
        }
    }

    var reqItemSysId = reqItemGR.insert();

    if (!reqItemSysId) {
        return {
            success: false,
            error: 'Failed to create requested item'
        };
    }

    return {
        success: true,
        request_number: reqGR.number.toString(),
        request_item_number: reqItemGR.number.toString(),
        catalog_item: catItemGR.name.toString(),
        quantity: args.quantity || 1,
        state: 'Submitted',
        approval_required: catItemGR.no_cart !== true,
        message: 'Request ' + reqGR.number + ' submitted successfully for ' + catItemGR.name + '. ' + 
                 (catItemGR.no_cart === true ? 'No approval required.' : 'Awaiting approval.')
    };
})(args, userId);
